# Code generated by Claude
"""
Tests of src/grasp_rules.py (the rules that make a hand pose a map grasp, design plan §3.1).

    MUJOCO_GL=egl python experiments/grasp_rules_test.py

1. The level rule on made-up hand rotations: approach elevation and finger-axis elevation at 4.9 and 5.1 degrees, either one failing fails the pose, the sign does not matter.
2. The bins: 12 bins that tile the circle, bin 0 forward (+-15 degrees), bin 3 to the left, bin 6 backward, bin 11 forward-right, on both sides of every boundary; rule_ok agrees
   with classify on random level poses (one bin each, and the bins together cover every level pose).
3. joint_bounds: both arms, every joint exactly 10 degrees inside its limits.
4. Yield: of random in-limit joint vectors (1M, left arm) the share with a level approach axis and a level finger axis is about 0.48 % (measured in the B2 read-through).
5. The IK constraint: pad-centre targets taken from random level poses of bin 0 (left arm) are solved from warm starts (the pose's joints plus 0.02 rad of noise) and from random starts; every
   solution satisfies the rule exactly as rule_ok says (level, bin 0), the position, and the joint margin; a target 5 cm from the shoulder can never be a level grasp.
"""

import math
import os
import sys
from pathlib import Path

PROJECT_ROOT = Path(__file__).resolve().parent.parent
sys.path.insert(0, str(PROJECT_ROOT))
if not os.environ.get("DISPLAY"):
    os.environ.setdefault("MUJOCO_GL", "egl")

import numpy as np  # noqa: E402

from src import robot_specs  # noqa: E402
from src.arm_kinematics import arm_chain, batch_fk, shoulder_origin, solve_ik  # noqa: E402
from src.grasp_rules import azimuth, bin_center, classify, joint_bounds, make_constraint, rule_ok  # noqa: E402
from src.simulator import RobotSimulator  # noqa: E402
from src.gripper_geometry import grasp_cfg  # noqa: E402

results = []
D = math.pi / 180


def check(name, ok, detail=""):
    results.append(bool(ok))
    print(f"  {'PASS' if ok else 'FAIL'}  {name}  {detail}")


def hand(approach_elev_deg, finger_elev_deg, azimuth_deg):
    """A hand rotation (1, 3, 3): approach axis at the elevation and azimuth, finger axis tilted by the given elevation out of the horizontal plane perpendicular to it."""
    e, az = approach_elev_deg * D, azimuth_deg * D
    z = np.array([math.cos(e) * math.cos(az), math.cos(e) * math.sin(az), math.sin(e)])
    side = np.cross([0, 0, 1.0], z)
    side /= np.linalg.norm(side)
    up = np.cross(z, side)
    f = finger_elev_deg * D
    y = math.cos(f) * side + math.sin(f) * up
    y -= (y @ z) * z
    y /= np.linalg.norm(y)
    x = np.cross(y, z)
    return np.stack([x, y, z], axis=1)[None]


def main():
    sim = RobotSimulator(pedestal_lift=robot_specs.PEDESTAL_SPECS, cameras=None)
    m = sim.model
    C = grasp_cfg(m, "left")
    print("\n1. the level rule")
    for ae, fe, want in ((0, 0, True), (4.9, 0, True), (5.1, 0, False), (-4.9, 0, True), (-5.1, 0, False), (0, 4.9, True), (0, 5.1, False), (0, -5.1, False), (4.9, -4.9, True), (30, 0, False)):
        got = classify(hand(ae, fe, 10.0), C)[0][0]
        check(f"approach elevation {ae:+.1f}, finger axis elevation {fe:+.1f}: {'level' if want else 'not level'}", got == want)

    print("\n2. the bins")
    for az, want in ((0, 0), (14.9, 0), (15.1, 1), (-14.9, 0), (-15.1, 11), (30, 1), (89, 3), (90, 3), (180, 6), (-90, 9), (-179, 6), (-30, 11), (165.1, 6), (164.9, 5)):
        got = int(classify(hand(0, 0, az), C)[1][0])
        check(f"approach azimuth {az:+.1f} deg is in bin {want}", got == want, f"got {got}")
    rng = np.random.default_rng(0)
    Rr = np.concatenate([hand(rng.uniform(-4, 4), rng.uniform(-4, 4), rng.uniform(-180, 180)) for _ in range(2000)])
    lev, kk = classify(Rr, C)
    counts = np.array([rule_ok(Rr, k, C).sum() for k in range(C["n_bins"])])
    check("2000 random level poses: each is in exactly one bin and rule_ok agrees with classify", lev.all() and counts.sum() == 2000 and all(rule_ok(Rr[kk == k], k, C).all() for k in range(12)),
          f"per bin {counts.tolist()}")
    check("bin centres are k * 30 degrees", abs(bin_center(3, C) - 90 * D) < 1e-12 and abs(bin_center(11, C) - 330 * D) < 1e-12)

    print("\n3. joint bounds with the margin")
    from src.robot_helpers import arm_ids
    for side in ("left", "right"):
        lo, hi = joint_bounds(m, side, C)
        rg = m.jnt_range[arm_ids(m, side)["jnt"]]
        check(f"{side}: every joint is exactly {C['joint_margin_deg']:g} degrees inside both limits", np.allclose(lo - rg[:, 0], 10 * D) and np.allclose(rg[:, 1] - hi, 10 * D))

    print("\n4. yield of random joint vectors (left arm, 1M)")
    chain = arm_chain(m, "left")
    lo, hi = joint_bounds(m, "left", C)
    Q = rng.uniform(lo, hi, (1_000_000, 7))
    _, R = batch_fk(chain, Q)
    lev, kk = classify(R, C)
    check("0.4 to 0.6 % of random vectors give a level approach axis and a level finger axis", 0.004 <= lev.mean() <= 0.006, f"{100 * lev.mean():.3f} % ({int(lev.sum())} poses), {int((lev & (kk == 0)).sum())} in bin 0")

    print("\n5. the IK constraint (left arm, bin 0)")
    idx = np.nonzero(lev & rule_ok(R, 0, C))[0][:1000]
    Qp = Q[idx]
    pad = np.array(C["pad_center_in_tcp"])
    target, _ = batch_fk(chain, Qp, pad)
    for name, Q0 in (("warm start (pose joints + 0.02 rad)", np.clip(Qp + rng.normal(0, 0.02, Qp.shape), lo, hi)), ("random start", rng.uniform(lo, hi, Qp.shape))):
        Qs, ok, it = solve_ik(chain, Q0, lo, hi, make_constraint(target, 0, C), pad, max_iter=C["ik_max_iter"], damping=C["ik_damping"], max_step=C["ik_max_step"])
        p, Rs = batch_fk(chain, Qs, pad)
        sat = rule_ok(Rs, 0, C) & (np.linalg.norm(p - target, axis=1) < C["ik_pos_tol"]) & (Qs >= lo - 1e-12).all(axis=1) & (Qs <= hi + 1e-12).all(axis=1)
        check(f"{name}: converged solutions satisfy the rule, the position and the joint margin", sat[ok].all(), f"{int(ok.sum())} of {len(ok)} converged, median {int(np.median(it[ok]))} iterations")
        if "warm" in name:
            check(f"{name}: at least 99 % converge", ok.mean() >= 0.99, f"{100 * ok.mean():.1f} %")
    close = np.tile(shoulder_origin(chain) + [0.05, 0.0, 0.0], (100, 1))
    _, ok, _ = solve_ik(chain, rng.uniform(lo, hi, (100, 7)), lo, hi, make_constraint(close, 0, C), pad, max_iter=C["ik_max_iter"])
    check("a target 5 cm in front of the shoulder is never a level grasp", not ok.any())
    print(f"\n{sum(results)}/{len(results)} checks passed")
    return all(results)


if __name__ == "__main__":
    sys.exit(0 if main() else 1)
